import urllib.request, json
# Search through all posts on commons.local
for post_id in range(1, 105):
    try:
        url = f'http://commons.local/api/posts/{post_id}'
        with urllib.request.urlopen(url) as resp:
            data = json.loads(resp.read().decode())
            body = data.get('body', '') + ' ' + (data.get('title') or '')
            for reply in data.get('replies', []):
                body += ' ' + reply.get('body', '')
            if 'price' in body.lower() or 'internal' in body.lower():
                print(f'Match in post {post_id}: {data.get(\"title\")}')
                print(body[:300])
                print('---')
    except Exception as e:
        pass
